            local rows, switches = {}, {}
            local function refreshRows()
                for v, b in pairs(rows) do
                    local selected = options.Multi and table.find(control.Value, v) ~= nil
                        or not options.Multi and control.Value == v
                    b.Text = '  ' .. v
                    ctx:Bind(b, 'TextColor3', selected and 'Accent' or 'Text')
                    if switches[v] then
                        ctx:Paint(switches[v][1], selected and 'Accent' or 'Field')
                        ctx:Paint(switches[v][2], selected and 'AccentText' or 'Muted')
                        switches[v][2].Position = UDim2.fromOffset(selected and 18 or 3, 3)
                    end
                end
            end
            for _, v in ipairs(entries) do
                local b = ctx:Button(
                    v,
                    list,
                    {
                        Size = UDim2.new(1, -4, 0, 28),
                        ZIndex = 102,
                        TextXAlignment = Enum.TextXAlignment.Left,
                    }
                )
                rows[v] = b
                if options.Multi then
                    local rail = ctx:New('Frame', {
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, -6, 0.5, 0),
                        Size = UDim2.fromOffset(32, 18),
                        ZIndex = 103,
                    }, b)
                    ctx:Stroke(rail)
                    local thumb = ctx:New('Frame', { Size = UDim2.fromOffset(11, 12), ZIndex = 104 }, rail)
                    switches[v] = { rail, thumb }
                end
                ctx:Connect(b.Activated, function()
                    if options.Multi then
                        local values = control:Get()
                        local index = table.find(values, v)
                        if index then
                            table.remove(values, index)
                        else
                            table.insert(values, v)
                        end
                        control:Set(values)
                        refreshRows()
                    else
                        control:Set(v)
                        ctx:ClosePopup()
                    end
                end, ctx.PopupConnections)
            end
            if searchHeight > 0 then
                local search = ctx:New('TextBox', {
                    Position = UDim2.fromOffset(6, 6),
                    Size = UDim2.new(1, -12, 0, 28),
                    PlaceholderText = 'Search…',
                    Text = '',
                    ClearTextOnFocus = false,
                    ZIndex = 102,
                }, popup)
                ctx:Paint(search, 'Field')
                ctx:Stroke(search)
                ctx:Connect(search:GetPropertyChangedSignal('Text'), function()
                    local query = string.lower(search.Text)
                    for v, b in pairs(rows) do
                        b.Visible = string.find(string.lower(v), query, 1, true) ~= nil
                    end
                end, ctx.PopupConnections)
            end
            if options.Multi then
                local all = ctx:Button('Select all', popup, {
                    Position = UDim2.fromOffset(6, 6 + searchHeight),
                    Size = UDim2.new(0.5, -9, 0, 28),
                    ZIndex = 102,
                })
                local clear = ctx:Button('Clear', popup, {
                    Position = UDim2.new(0.5, 3, 0, 6 + searchHeight),
                    Size = UDim2.new(0.5, -9, 0, 28),
                    ZIndex = 102,
                })
                ctx:Connect(all.Activated, function()
                    control:Set(entries)
                    refreshRows()
                end, ctx.PopupConnections)
                ctx:Connect(clear.Activated, function()
                    control:Set({})
                    refreshRows()
                end, ctx.PopupConnections)
            end
            refreshRows()
        end)
        return control
    end

    function section:Keybind(options)
        local frame = row(ctx, body, options.Text or 'Keybind', nil, options.Description)
        local button = ctx:Button('', frame, fieldProps())
        local control = register(ctx, options, { Value = Enum.KeyCode.Unknown, OnPress = options.OnPress })
        function control:Refresh()
            button.Text = self.Value == Enum.KeyCode.Unknown and 'Unbound' or self.Value.Name
        end
        function control:Set(value, silent)
            if typeof(value) ~= 'EnumItem' or value.EnumType ~= Enum.KeyCode then
                return false
            end
            self.Value = value
            self:Refresh()
            if not silent then
                ctx:Callback(options.Callback, value)
            end
            return true
        end
        control:Set(options.Default or Enum.KeyCode.Unknown, true)
        ctx.Keybinds[control] = true
        ctx:Connect(button.Activated, function()
            button.Text = 'Press a key…'
            ctx.CaptureKey = function(key)
                control:Set(key == Enum.KeyCode.Escape and Enum.KeyCode.Unknown or key)
            end
        end)
        return control
    end

    function section:ColorPicker(options)
        local frame = row(ctx, body, options.Text or 'Color', nil, options.Description)
        local button = ctx:Button('', frame, fieldProps())
        local swatch =
            ctx:New('Frame', { Position = UDim2.fromOffset(5, 5), Size = UDim2.new(1, -10, 1, -10) }, button)
        local control = register(ctx, options, { Value = options.Default or ctx.Theme.Accent })
        function control:Refresh()
            swatch.BackgroundColor3 = self.Value
        end
        function control:Set(value, silent)
            if typeof(value) ~= 'Color3' then
                return false
            end
            self.Value = value
            self:Refresh()
            if not silent then
                ctx:Callback(options.Callback, value)
            end
            return true
        end
        control:Refresh()
        ctx:Connect(button.Activated, function()
            if ctx.PopupAnchor == button then
                ctx:ClosePopup()
                return
            end
            local popup = ctx:OpenPopup(button, 242, 240)
            local hue, sat, val = control.Value:ToHSV()
            local square = ctx:New('Frame', {
                Position = UDim2.fromOffset(10, 10),
                Size = UDim2.new(1, -20, 0, 166),
                Active = true,
                ZIndex = 101,
            }, popup)
            local white = ctx:New(
                'Frame',
                { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 102 },
                square
            )
            ctx:New('UIGradient', { Transparency = NumberSequence.new(0, 1) }, white)
            local black = ctx:New(
                'Frame',
                { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), ZIndex = 103 },
                square
            )
            ctx:New('UIGradient', { Rotation = 90, Transparency = NumberSequence.new(1, 0) }, black)
            local cursor = ctx:New('Frame', {
                Size = UDim2.fromOffset(7, 7),
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = Color3.new(1, 1, 1),
                ZIndex = 104,
            }, square)
            ctx:Stroke(cursor)
            local strip = ctx:New('Frame', {
                Position = UDim2.fromOffset(10, 185),
                Size = UDim2.new(1, -20, 0, 16),
                BackgroundColor3 = Color3.new(1, 1, 1),
                Active = true,
                ZIndex = 101,
            }, popup)
            local colors = {}
            for i = 0, 6 do
                table.insert(colors, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(i / 6, 1, 1)))
            end
            ctx:New('UIGradient', { Color = ColorSequence.new(colors) }, strip)
            local hueMarker = ctx:New('Frame', {
                Size = UDim2.fromOffset(3, 20),
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundColor3 = Color3.new(1, 1, 1),
                ZIndex = 102,
            }, strip)
            local hex = ctx:New('TextBox', {
                Position = UDim2.fromOffset(10, 207),
                Size = UDim2.new(1, -20, 0, 25),
                BackgroundTransparency = 1,
                ClearTextOnFocus = false,
                ZIndex = 102,
            }, popup)
            local function refresh()
                square.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
                cursor.Position = UDim2.fromScale(sat, 1 - val)
                hueMarker.Position = UDim2.new(hue, 0, 0, -2)
                hex.Text = '#' .. control.Value:ToHex()
            end
            ctx:Pointer(square, function(pos)
                sat =
                    math.clamp((pos.X - square.AbsolutePosition.X) / math.max(1, square.AbsoluteSize.X), 0, 1)
                val = 1
                    - math.clamp(
                        (pos.Y - square.AbsolutePosition.Y) / math.max(1, square.AbsoluteSize.Y),
                        0,
                        1
                    )
                control:Set(Color3.fromHSV(hue, sat, val))
                refresh()
            end, nil, ctx.PopupConnections)
            ctx:Pointer(strip, function(pos)
                hue = math.clamp((pos.X - strip.AbsolutePosition.X) / math.max(1, strip.AbsoluteSize.X), 0, 1)
                control:Set(Color3.fromHSV(hue, sat, val))
                refresh()
            end, nil, ctx.PopupConnections)
            ctx:Connect(hex.FocusLost, function()
                local value = hex.Text:gsub('^#', '')
                if #value == 6 and value:match('^%x+$') then
                    control:Set(Color3.fromHex(value))
                    hue, sat, val = control.Value:ToHSV()
                end
                refresh()
            end, ctx.PopupConnections)
            refresh()
        end)
        return control
    end
    return section
end
return Components

end
factories['Window'] = function()
local Core = get('Core')
local Components = get('Components')
local Http = game:GetService('HttpService')
local Window = {}
function Window.new(options, profiles)
    options = options or {}
    local player = game:GetService('Players').LocalPlayer
    assert(options.Parent or player, 'MintProject must run in a client UI context')
    local parent = options.Parent or player:WaitForChild('PlayerGui')
    local ctx = Core.new(parent, options)
    local self =
        { Context = ctx, Tabs = {}, Profiles = profiles or {}, Visible = true, Version = '0.1.0-preview' }
    local gui = ctx:New('ScreenGui', {
        Name = options.Name or 'MintProjectUI',
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 50,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
    }, parent)
    ctx.Gui = gui
    local viewport = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
        or Vector2.new(1000, 700)
    local size = Vector2.new(
        math.min(options.Width or 790, viewport.X - 20),
        math.min(options.Height or 520, viewport.Y - 20)
    )
    local root = ctx:New('CanvasGroup', {
        Name = 'Window',
        Size = UDim2.fromOffset(size.X, size.Y),
        Position = UDim2.fromOffset(
            math.round(math.max(10, (viewport.X - size.X) / 2)),
            math.round(math.max(10, (viewport.Y - size.Y) / 2))
        ),
        GroupTransparency = 1,
        Active = true,
    }, gui)
    ctx:Paint(root, 'Background')
    ctx:Stroke(root)
    self.Root = root
    local header = ctx:New('Frame', { Size = UDim2.new(1, 0, 0, 42), Active = true }, root)
    ctx:Paint(header, 'Panel')
    ctx:Text(
        options.Title or 'MintProject',
        header,
        { Position = UDim2.fromOffset(14, 8), Size = UDim2.new(1, -95, 0, 26), TextSize = 18 }
    )
    local gloss = ctx:New('Frame', { Size = UDim2.new(1, 0, 0, 1), BackgroundTransparency = 0.25 }, header)
    ctx:Paint(gloss, 'White')
    ctx:New('UIGradient', {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.9),
            NumberSequenceKeypoint.new(0.5, 0.15),
            NumberSequenceKeypoint.new(1, 0.9),
        }),
    }, gloss)
    local close =
        ctx:Button('×', header, { Position = UDim2.new(1, -38, 0, 7), Size = UDim2.fromOffset(28, 28) })
    ctx:Connect(close.Activated, function()
        self:SetVisible(false)
    end)
    local tabs = ctx:New('ScrollingFrame', {
        Position = UDim2.fromOffset(10, 48),
        Size = UDim2.new(1, -20, 0, 32),
        BackgroundTransparency = 1,
        CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.X,
        ScrollingDirection = Enum.ScrollingDirection.X,
        ScrollBarThickness = 0,
    }, root)
    ctx:List(tabs, 6, true)
    local body = ctx:New(
        'Frame',
        { Position = UDim2.fromOffset(10, 90), Size = UDim2.new(1, -20, 1, -100), BackgroundTransparency = 1 },
        root
    )
    local open = ctx:Button(
        'M',
        gui,
        { Position = UDim2.new(0, 14, 1, -48), Size = UDim2.fromOffset(34, 32), ZIndex = 20 }
    )
    ctx:Bind(open, 'TextColor3', 'Accent')
    ctx:Connect(open.Activated, function()
        self:SetVisible(not self.Visible)
    end)
    local notices = ctx:New('Frame', {
        AnchorPoint = Vector2.new(1, 1),
        Position = UDim2.new(1, -16, 1, -16),
        Size = UDim2.fromOffset(math.min(280, viewport.X - 30), 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        ZIndex = 90,
    }, gui)
    local nl = ctx:List(notices, 6)
    nl.VerticalAlignment = Enum.VerticalAlignment.Bottom
    ctx.ToggleKey = options.ToggleKey or Enum.KeyCode.RightShift
    ctx.ToggleVisible = function()
        self:SetVisible(not self.Visible)
    end
    local startInput, startPos
    ctx:Connect(header.InputBegan, function(input)
        if
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        then
            startInput = input.Position
            startPos = root.AbsolutePosition
        end
    end)
    ctx:Pointer(header, function(pos)
        if not startPos then
            return
        end
        local d = pos - startInput
        local v = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or viewport
        root.Position = UDim2.fromOffset(
            math.clamp(startPos.X + d.X, 0, math.max(0, v.X - size.X)),
            math.clamp(startPos.Y + d.Y, 0, math.max(0, v.Y - 42))
        )
    end)
    function self:SetVisible(value)
        if ctx.Destroyed then
            return
        end
        self.Visible = value == true
        ctx:ClosePopup()
        self.VisibilitySequence = (self.VisibilitySequence or 0) + 1
        local seq = self.VisibilitySequence
        if self.Visible then
            root.Visible = true
            ctx:Animate(root, { GroupTransparency = 0 })
        else
            ctx:Animate(root, { GroupTransparency = 1 })
            task.delay(ctx.Animations and 0.18 or 0, function()
                if not ctx.Destroyed and self.VisibilitySequence == seq then
                    root.Visible = false
                end
            end)
        end
    end
    function self:SetTheme(patch)
        ctx:SetTheme(patch)
    end
    function self:SetAnimations(value)
        ctx.Animations = value == true
    end
    function self:SetToggleKey(key)
        assert(typeof(key) == 'EnumItem' and key.EnumType == Enum.KeyCode, 'Expected KeyCode')
        ctx.ToggleKey = key
    end
    function self:Notify(text, duration)
        if ctx.Destroyed then
            return
        end
        local n = ctx:New('Frame', { Size = UDim2.new(1, 0, 0, 58), ZIndex = 90 }, notices)
        ctx:Paint(n, 'Panel')
        ctx:Stroke(n)
        ctx:Text(
            tostring(text),
            n,
            {
                Position = UDim2.fromOffset(10, 6),
                Size = UDim2.new(1, -20, 1, -12),
                TextWrapped = true,
                ZIndex = 91,
            }
        )
        task.delay(duration or 3, function()
            if n.Parent then
                n:Destroy()
            end
        end)
    end
    function self:Tab(name)
        local tab = { Name = name }
        local button =
            ctx:Button(name, tabs, { Size = UDim2.fromOffset(math.clamp(#name * 8 + 22, 80, 180), 30) })
        local page = ctx:New('ScrollingFrame', {
            Size = UDim2.fromScale(1, 1),
            Visible = false,
            BackgroundTransparency = 1,
            CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 0,
            ScrollingDirection = Enum.ScrollingDirection.Y,
        }, body)
        ctx:Bind(page, 'ScrollBarImageColor3', 'Accent')
        ctx:List(page, 8)
        ctx:Padding(page, 2)
        ctx:Connect(page:GetPropertyChangedSignal('CanvasPosition'), function()
            ctx:ClosePopup()
            page.ScrollBarThickness = 3
            tab.ScrollSequence = (tab.ScrollSequence or 0) + 1
            local seq = tab.ScrollSequence
            task.delay(0.7, function()
                if not ctx.Destroyed and seq == tab.ScrollSequence then
                    page.ScrollBarThickness = 0
                end
            end)
        end)
        function tab:Select()
            ctx:ClosePopup()
            for _, t in ipairs(self.Owner.Tabs) do
                t.Page.Visible = t == self
                ctx:Paint(t.Button, t == self and 'Hover' or 'Field')
                ctx:Bind(t.Button, 'TextColor3', t == self and 'Accent' or 'Text')
            end
        end
        function tab:Section(title)
            return Components.section(ctx, page, title)
        end
        tab.Owner = self
        tab.Page = page
        tab.Button = button
        self.Tabs[#self.Tabs + 1] = tab
        ctx:Connect(button.Activated, function()
            tab:Select()
        end)
        if #self.Tabs == 1 then
            tab:Select()
        end
        return tab
    end
    function self:ExportConfig()
        local values = {}
        for id, c in pairs(ctx.Controls) do
            if typeof(c.Value) == 'Color3' then
                values[id] = { type = 'color', r = c.Value.R, g = c.Value.G, b = c.Value.B }
            elseif typeof(c.Value) == 'EnumItem' then
                values[id] = { type = 'key', name = c.Value.Name }
            else
                values[id] = c.Value
            end
        end
        return Http:JSONEncode({ version = 1, values = values })
    end
    function self:ImportConfig(json)
        local ok, data = pcall(Http.JSONDecode, Http, json)
        if not ok or type(data) ~= 'table' or data.version ~= 1 or type(data.values) ~= 'table' then
            return false, 'Invalid MintProject profile'
        end
        local failed = {}
        for id, value in pairs(data.values) do
            local c = ctx.Controls[id]
            if c then
                if type(value) == 'table' and value.type == 'color' then
                    local r, g, b =
                        Core.number(value.r, 0, 1), Core.number(value.g, 0, 1), Core.number(value.b, 0, 1)
                    value = r and g and b and Color3.new(r, g, b) or nil
                elseif type(value) == 'table' and value.type == 'key' then
                    local good, key = pcall(function()
                        return Enum.KeyCode[value.name]
                    end)
                    value = good and key or nil
                end
                local good, result = pcall(c.Set, c, value)
                if not good or result == false then
                    failed[#failed + 1] = id
                end
            end
        end
        return #failed == 0, table.concat(failed, ', ')
    end
    function self:SaveProfile(name)
        assert(type(name) == 'string' and #name > 0, 'Profile name is empty')
        self.Profiles[name] = self:ExportConfig()
        return self.Profiles[name]
    end
    function self:LoadProfile(name)
        if not self.Profiles[name] then
            return false, 'Profile not found'
        end
        return self:ImportConfig(self.Profiles[name])
    end
    function self:Destroy()
        ctx:Destroy()
    end
    self:SetVisible(true)
    return self
end
return Window

end
factories['init'] = function()
local Window = get('Window')
local Components = get('Components')
local MintProject = { Version = '0.1.0-preview', Windows = {}, Profiles = {} }

function MintProject:RegisterComponent(name, builder)
    Components.register(name, builder)
end

function MintProject:CreateWindow(options)
    local window = Window.new(options, self.Profiles)
    table.insert(self.Windows, window)
    return window
end

function MintProject:Destroy()
    for _, window in ipairs(self.Windows) do
        window:Destroy()
    end
    table.clear(self.Windows)
end

return MintProject

end
get = function(name)
    if cache[name] == nil then
        assert(factories[name], 'Unknown MintProject module: ' .. tostring(name))
        cache[name] = factories[name]()
    end
    return cache[name]
end
return get('init')

end)()
